import { test } from 'node:test';
import assert from 'node:assert/strict';
import { slugify } from '../src/utils/slugify.js';

test('lowercases and hyphenates words', () => {
  assert.equal(slugify('Hello World'), 'hello-world');
});

test('strips punctuation', () => {
  assert.equal(slugify('Hello, World!'), 'hello-world');
});

test('collapses repeated separators and whitespace', () => {
  assert.equal(slugify('a   b\t\nc'), 'a-b-c');
  assert.equal(slugify('a --- b'), 'a-b');
});

test('trims leading and trailing separators', () => {
  assert.equal(slugify('  --Hello--  '), 'hello');
  assert.equal(slugify('!!!hi!!!'), 'hi');
});

test('removes diacritics', () => {
  assert.equal(slugify('Café Crème Brûlée'), 'cafe-creme-brulee');
});

test('keeps digits', () => {
  assert.equal(slugify('Top 10 Notes of 2024'), 'top-10-notes-of-2024');
});

test('returns empty string when nothing slug-worthy remains', () => {
  assert.equal(slugify(''), '');
  assert.equal(slugify('   '), '');
  assert.equal(slugify('!!!'), '');
  assert.equal(slugify('日本語'), '');
});

test('coerces non-string input', () => {
  assert.equal(slugify(123), '123');
});
